<?php
 namespace Pterodactyl\Services\Dezerx\AutoAction; use Throwable; use Carbon\CarbonImmutable; use Illuminate\Support\Facades\Log; use Illuminate\Database\Eloquent\Collection; use Pterodactyl\Facades\Activity; use Pterodactyl\Models\Dezerx\AutoAction; use Pterodactyl\Services\Servers\SuspensionService; use Pterodactyl\Services\Servers\ServerDeletionService; class AutoActionRunner { public function __construct(private SuspensionService $suspension) { } public function due(): Collection { $cutoff = CarbonImmutable::now()->subMinutes(AutoActions::graceMinutes()); return AutoAction::query() ->with('server') ->whereNull('processed_at') ->where('due_at', '<=', $cutoff) ->orderBy('due_at') ->get(); } public function handle(AutoAction $entry): string { $server = $entry->server; if ($server === null) { $entry->delete(); return 'orphaned'; } $action = AutoActions::action($entry->action); Activity::event('server:auto-action.run') ->subject($server) ->property([ 'action' => $action, 'due_at' => $entry->due_at?->toIso8601String(), ]) ->log(); if ($action === AutoActions::SUSPEND) { $outcome = $server->isSuspended() ? AutoActions::OUTCOME_ALREADY_SUSPENDED : AutoActions::OUTCOME_SUSPENDED; if ($outcome === AutoActions::OUTCOME_SUSPENDED) { $this->suspension->toggle($server, SuspensionService::ACTION_SUSPEND); } $entry->forceFill([ 'attempts' => $entry->attempts + 1, 'processed_at' => CarbonImmutable::now(), 'outcome' => $outcome, 'failure' => null, ])->save(); Log::notice('Auto action suspended a server', ['server' => $server->uuid, 'outcome' => $outcome]); return $outcome; } $force = $action === AutoActions::FORCE_DELETE; $uuid = $server->uuid; app(ServerDeletionService::class)->withForce($force)->handle($server); $outcome = $force ? AutoActions::OUTCOME_FORCE_DELETED : AutoActions::OUTCOME_DELETED; Log::notice('Auto action deleted a server', ['server' => $uuid, 'outcome' => $outcome]); return $outcome; } public function fail(AutoAction $entry, Throwable $exception): void { $attempts = $entry->attempts + 1; $exhausted = $attempts >= AutoActions::MAX_ATTEMPTS; $entry->forceFill([ 'attempts' => $attempts, 'failure' => mb_substr($exception->getMessage(), 0, 500), 'processed_at' => $exhausted ? CarbonImmutable::now() : null, 'outcome' => $exhausted ? AutoActions::OUTCOME_FAILED : null, ])->save(); Log::warning('Auto action could not run', [ 'server' => $entry->server?->uuid, 'action' => $entry->action, 'attempts' => $attempts, 'giving_up' => $exhausted, 'error' => $exception->getMessage(), ]); } } 